+	case REPARSE_TAG_LX_CHR:
+	case REPARSE_TAG_LX_BLK:
+		if (length == 0)
+			break;
+		/* fallthrough */
 	default:
 		proto_tree_add_item(tree, hf_smb2_unknown, tvb, offset, length, ENC_NA);
 	}
